import { HashRouter, Routes, Route } from "react-router-dom";
import TimeImportIncentive from "./pages/TimeImportIncentive";
import TimeImportDiligence from "./pages/TimeImportDiligence";
import Login from "./pages/Login";
import { Container, Nav, Navbar, NavDropdown } from "react-bootstrap";
import { useState } from "react";

function App() {
  const [isAuth, setIsAuth] = useState(
    localStorage.getItem("isLoggedIn") === "true",
  );
  if (isAuth) {
    return (
      <HashRouter>
        <Navbar expand="lg" className="bg-body-tertiary">
          <Container>
            <Navbar.Brand href="#">TAURUS</Navbar.Brand>
            <Navbar.Toggle aria-controls="basic-navbar-nav" />
            <Navbar.Collapse id="basic-navbar-nav">
              <Nav className="me-auto">
                <Nav.Link href="#">Home</Nav.Link>
                <Nav.Link href="#">Link</Nav.Link>
                <NavDropdown title="Import" id="basic-nav-dropdown">
                  <NavDropdown.Item href="#/import/incentive">
                    Incentive
                  </NavDropdown.Item>
                  <NavDropdown.Item href="#/import/diligence">
                    Diligence
                  </NavDropdown.Item>
                  <NavDropdown.Divider />
                  <NavDropdown.Item href="#">Soon</NavDropdown.Item>
                </NavDropdown>
              </Nav>
            </Navbar.Collapse>
          </Container>
        </Navbar>
        <Container>
          <Routes>
            <Route path="/import/incentive" element={<TimeImportIncentive />} />
            <Route path="/import/diligence" element={<TimeImportDiligence />} />
            <Route
              path="*"
              element={
                <div className="app-page">
                  <h1>Welcome</h1>
                  <p>taurus</p>
                </div>
              }
            />
          </Routes>
        </Container>
      </HashRouter>
    );
  } else {
    return <Login setAuth={() => setIsAuth(true)} />;
  }
}

export default App;
