import React, { useState } from "react";
import Button from "react-bootstrap/esm/Button";
import Table from "react-bootstrap/esm/Table";
import Form from "react-bootstrap/Form";
import InputGroup from "react-bootstrap/InputGroup";
import { exportToExcelV2 } from "../services/xlsx.service";

const TimeImportDiligence: React.FC = () => {
  const [records, setRecords] = useState([] as any[]);
  const [aaa, setAAA] = useState("");
  const [bbb, setBBB] = useState("");
  const [ccc, setCCC] = useState("");

  const handleAddRecord = () => {
    const newRecord = { aaa, bbb, ccc };
    setRecords([...records, newRecord]);
  };
  const handleExport = () => {
    exportToExcelV2(records);
  };
  const handleRemoveRecord = (index: number) => {
    const newRecords = [...records];
    newRecords.splice(index, 1);
    setRecords(newRecords);
  };
  return (
    <>
      <br />
      <InputGroup className="mb-3">
        <InputGroup.Text id="basic-addon1">@</InputGroup.Text>
        <Form.Control
          placeholder="1"
          aria-label="1"
          aria-describedby="basic-addon1"
          onChange={(e) => setAAA(e.target.value)}
        />
      </InputGroup>
      <InputGroup className="mb-3">
        <InputGroup.Text id="basic-addon1">@</InputGroup.Text>
        <Form.Control
          placeholder="2"
          aria-label="2"
          aria-describedby="basic-addon1"
          onChange={(e) => setBBB(e.target.value)}
        />
      </InputGroup>
      <InputGroup className="mb-3">
        <InputGroup.Text id="basic-addon1">@</InputGroup.Text>
        <Form.Control
          placeholder="3"
          aria-label="3"
          aria-describedby="basic-addon1"
          onChange={(e) => setCCC(e.target.value)}
        />
      </InputGroup>
      <Button
        variant="danger"
        type="submit"
        className="w-100"
        onClick={handleAddRecord}
      >
        Add
      </Button>
      <Button
        variant="primary"
        type="submit"
        className="w-100"
        onClick={handleExport}
      >
        Export
      </Button>
      <br />
      <br />
      <Table striped bordered hover size="sm">
        <thead>
          <tr>
            <th>#</th>
            <th>First Name</th>
            <th>Last Name</th>
            <th>Username</th>
          </tr>
        </thead>
        <tbody>
          {records.map((record, index) => (
            <tr key={index}>
              <td>{index + 1}</td>
              <td>{record.aaa}</td>
              <td>{record.bbb}</td>
              <td>{record.ccc}</td>
              <td>
                {" "}
                <Button
                  variant="danger"
                  className="w-100"
                  onClick={handleRemoveRecord.bind(null, index)}
                >
                  Remove
                </Button>
              </td>
            </tr>
          ))}
        </tbody>
      </Table>
    </>
  );
};

export default TimeImportDiligence;
