import { Alert, Button, Container, Form } from "react-bootstrap";
import React, { useState } from "react";

type LoginProps = {
  setAuth: () => void;
};

const LoginPage: React.FC<LoginProps> = ({ setAuth }) => {
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();

    setError("");

    if (!password) {
      setError("Service-key is required");
      return;
    }
    const d = new Date();
    const currentDate = d.getFullYear() + "|";

    if (password.includes(currentDate)) {
      localStorage.setItem("isLoggedIn", "true");
      setAuth();
    } else {
      setError("Invalid service-key");
    }
  };
  return (
    <>
      <Container className="mt-5" style={{ maxWidth: "400px" }}>
        <h3 className="mb-4">Login</h3>

        {error && <Alert variant="danger">{error}</Alert>}

        <Form onSubmit={handleLogin}>
          <Form.Group className="mb-3">
            <Form.Label htmlFor="inputPassword">service-key</Form.Label>
            <Form.Control
              type="password"
              id="inputPassword"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
            />
            <Form.Text>
              Please contact your administrator for the service-key.
            </Form.Text>
          </Form.Group>

          <Button variant="primary" type="submit" className="w-100">
            check
          </Button>
        </Form>
      </Container>
    </>
  );
};

export default LoginPage;
